import { AfterViewInit, Directive, Injector, TemplateRef, ViewChild } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { AdminHeaderService } from 'espd-common/admin-header';
import { NavigationService } from 'espd-common/navigation';
import { UnsubscribeOnDestroyDirective } from 'espd-common/utils';

const loadingDelaySeconds: number = 2;
const loadingDisplayMinSeconds: number = 1;

@Directive()
export abstract class AbstractEntityComponent extends UnsubscribeOnDestroyDirective implements AfterViewInit {

	@ViewChild('entityHeadingTemplate')
	public entityHeadingTemplateRef?: TemplateRef<any>;

	private _isFirstLoad: boolean = true;
	protected isLoading: boolean = false;
	protected route: ActivatedRoute;

	private adminHeaderService: AdminHeaderService | null;

	private loadingIndicatorActive: boolean = false;
	private loadingDelayComplete: boolean = false;
	private timerId?: number;

	constructor(protected injector: Injector) {
		super();
		this.adminHeaderService = injector.get(AdminHeaderService, undefined, { optional: true });
		this.route = this.injector.get(ActivatedRoute);
	}

	protected get isFirstLoad(): boolean {
		return this._isFirstLoad;
	}

	public get showLoadingIndicator(): boolean {
		return this.loadingIndicatorActive;
	}

	public get showData(): boolean {
		return !this.isLoading && !this.loadingIndicatorActive;
	}

	public ngAfterViewInit(): void {
		if (this.entityHeadingTemplateRef) {
			this.adminHeaderService?.setHeaderTemplate(this.entityHeadingTemplateRef);
		}
	}

	public goBack(): void {
		this.injector.get(NavigationService).back(['..'], { relativeTo: this.injector.get(ActivatedRoute) });
	}

	public startInitialLoad(): void {
		if (!this.isLoading) {
			this.isLoading = true;
			this.loadingDelayComplete = false;
			this.timerId = setTimeout(() => {
				this.loadingIndicatorActive = true;
				this.timerId = undefined;
				setTimeout(() => {
					this.loadingIndicatorActive = this.isLoading;
					this.loadingDelayComplete = true;
				}, loadingDisplayMinSeconds * 1000);
			}, loadingDelaySeconds * 1000) as unknown as number;
		}
	}

	public doneLoading(): void {
		this.isLoading = false;
		this._isFirstLoad = false;
		if (!this.loadingIndicatorActive) {
			clearTimeout(this.timerId);
			this.timerId = undefined;
		}

		if (this.loadingIndicatorActive && this.loadingDelayComplete) {
			this.loadingIndicatorActive = false;
		}
	}
}