import { Component, ElementRef, EventEmitter, Injector, Input, Output, TemplateRef, ViewChild } from '@angular/core';
import { FormControl, UntypedFormGroup } from '@angular/forms';
import { Page, emptyPage } from 'espd-common/data';
import { SearchComponent } from 'espd-common/forms/search';
import { MessageConfig, MessageService } from 'espd-common/i18n';
import { ActionsGenerator } from 'espd-common/layout/actions';
import { ColumnDefinition, RowItem, SectionConfig } from 'espd-common/layout/table';
import { SingleStepModalComponent } from 'espd-common/modal';
import { Observable } from 'rxjs';
import { AbstractEntityComponent } from '../abstract-entity/abstract-entity.component';

@Component({
    selector: 'espd-entity-list-scaffold',
    templateUrl: './entity-list-scaffold.component.html',
    styleUrls: ['./entity-list-scaffold.component.scss'],
    standalone: false
})
export class EntityListScaffoldComponent extends AbstractEntityComponent {

	@Input()
	public searchPlaceholder: string | MessageConfig = '';

	@Input()
	public searchLabel: string | MessageConfig = '';

	@Input()
	public page: Page<RowItem> = emptyPage;

	@Input()
	public columns: ColumnDefinition[] = [];

	@Input()
	public actionGenerator?: ActionsGenerator;

	@Input()
	public sectionConfig?: SectionConfig;

	@Input()
	public disableSearch: boolean = false;

	@Input()
	public disableFilter: boolean = false;

	@Output()
	public pageChanged: EventEmitter<number> = new EventEmitter<number>();

	@Output()
	/* eslint-disable @angular-eslint/no-output-native */
	public search: EventEmitter<string> = new EventEmitter<string>();

	@ViewChild('table', { read: ElementRef })
	private tableElement!: ElementRef;

	@ViewChild('search')
	private searchComponent?: SearchComponent;

	@ViewChild('deleteModal')
	private deleteModal!: SingleStepModalComponent;

	public form: UntypedFormGroup = new UntypedFormGroup({ search: new FormControl<string>('') });

	constructor(injector: Injector, private messageService: MessageService) {
		super(injector);
		this.startInitialLoad();
	}

	public doneLoading(scroll: boolean = false): void {
		super.doneLoading();
		if (scroll) {
			setTimeout(() => {
				this.tableElement.nativeElement.scrollIntoView({ behavior: 'smooth', block: 'start' });
			});
		}
	}

	public setSearchText(text: string | null): void {
		if (!this.disableSearch && this.searchComponent) {
			this.searchComponent.control.reset(text || '');
		}
	}

	public doSearch(text: string): void {
		this.search.emit(text);
	}

	public doPageChange(page: number): void {
		if (this.page.number !== page)
			this.pageChanged.emit(page);
	}

	public showDeleteModal(title: MessageConfig | string, body: MessageConfig | string | TemplateRef<any> | undefined, action: () => Observable<boolean>, successMessage: MessageConfig | string): Observable<boolean | undefined> {
		return this.deleteModal.show(title, body, this.messageService.get('common.delete'), action, successMessage);
	}
}