import { AfterViewInit, Component, Input, TemplateRef, ViewChild } from '@angular/core';
import { ControlContainer, FormGroupDirective } from '@angular/forms';
import { ActivatedRoute } from '@angular/router';
import { AdminHeaderService } from 'espd-common/admin-header';
import { BreadcrumbConfig } from 'espd-common/breadcrumb';
import { ButtonConfig } from 'espd-common/button';
import { EspdFormGroup } from 'espd-common/forms/api';
import { MessageConfig } from 'espd-common/i18n';
import { NavigationService } from 'espd-common/navigation';
import { AbstractEntityDetailComponent } from '../abstract-entity-detail/abstract-entity-detail.component';

@Component({
    selector: 'espd-entity-detail-scaffold',
    templateUrl: './entity-detail-scaffold.component.html',
    styleUrls: ['./entity-detail-scaffold.component.scss'],
    providers: [
        // This is hacky, but it works for now...
        { provide: ControlContainer, useExisting: EntityDetailScaffoldComponent },
        { provide: FormGroupDirective, useExisting: EntityDetailScaffoldComponent }
    ],
    standalone: false
})
export class EntityDetailScaffoldComponent extends ControlContainer implements AfterViewInit {

	@Input()
	public heading: MessageConfig | string = '';

	@Input()
	public breadcrumbConfigs: BreadcrumbConfig[] = [];

	@Input()
	public buttons?: ButtonConfig[];

	@Input()
	public backNavigationFallback: string[] = ['..'];

	@ViewChild('adminHeadingTemplate')
	public adminHeadingTemplateRef!: TemplateRef<any>;

	public get control(): EspdFormGroup {
		return this.detailComponent.form;
	}

	public get form(): EspdFormGroup {
		return this.detailComponent.form;
	}

	public get pendingSave(): boolean {
		return this.detailComponent.pendingSave;
	}

	constructor(
		private detailComponent: AbstractEntityDetailComponent<any, any, any>,
		private adminHeaderService: AdminHeaderService,
		private navigationService: NavigationService,
		private activatedRoute: ActivatedRoute
	) {
		super();
	}

	public ngAfterViewInit(): void {
		if (this.adminHeadingTemplateRef) {
			this.adminHeaderService.setHeaderTemplate(this.adminHeadingTemplateRef);
		}
	}

	public goBack(): void {
		this.navigationService.back(this.backNavigationFallback, { relativeTo: this.activatedRoute });
	}

	public onSave(): void {
		this.detailComponent.save();
	}
}