import { HttpResponse } from '@angular/common/http';
import { Directive, Inject, Injector, OnInit } from '@angular/core';
import { AbstractControl } from '@angular/forms';
import { RestDataService } from 'espd-common/data';
import { EspdFormGroup } from 'espd-common/forms/api';
import { Observable, of } from 'rxjs';
import { finalize } from 'rxjs/operators';
import { AbstractEntityComponent } from '../abstract-entity/abstract-entity.component';
import { Entity } from './entity.model';

@Directive()
export abstract class AbstractEntityDetailComponent<TEntity extends Entity, TService extends RestDataService<TEntity>, TFormModel extends {
	[K in keyof TFormModel]: AbstractControl<any>;
} = any> extends AbstractEntityComponent implements OnInit {

	public form!: EspdFormGroup<TFormModel>;
	public pendingSave: boolean = false;

	protected entity: TEntity | null = null;
	protected service: TService;

	constructor(injector: Injector, @Inject(null) service: TService, @Inject(null) private idPropertyName: string) {
		// TODO: remove idPropertyName parameter when we have the standard id field on Entity
		super(injector);
		this.service = service;
	}

	protected abstract createForm(): EspdFormGroup<TFormModel>;
	protected abstract resetForm(): void;
	protected newEntity?(): TEntity | Observable<TEntity>;
	protected abstract prepareSave(): TEntity;

	/**
	 * If you need to perform an action or check before doing the save,
	 * you can implement this and return an observable with a boolean value of whether to proceed with the save.
	 */
	protected beforeSave?(): Observable<boolean>;

	/**
	 * If you need to call a save method on the service other than just save(entity, form), this allows you to override that function.
	 * You can implement this and return an observable with the server response. If the afterSave method is implemented, it will still be called.
	 */
	protected onSave?(entity: TEntity): Observable<HttpResponse<any>>;

	/**
	 * If you need to perform an action other than backward navigation after a successful save,
	 * you can implement this function. If you want no no action, implement this function and do nothing.
	 */
	protected afterSave?(response: HttpResponse<any>): void;

	public ngOnInit(): void {
		this.form = this.createForm();

		this.fetchEntity(this.route.snapshot.paramMap.get('id')).subscribe(result => {
			this.entity = result;
			this.resetForm();
		});
	}

	public get isEdit(): boolean {
		return !!(this.entity as any)?.[this.idPropertyName];
	}

	public save(): void {
		(this.beforeSave ? this.beforeSave() : of(true)).subscribe(result => {
			if (result) {
				this.doSave();
			}
		});
	}

	private getObjectToSave(): TEntity {
		const objToSave: TEntity = this.prepareSave();
		(objToSave as any)[this.idPropertyName] = (this.entity as any)?.[this.idPropertyName] || null;
		objToSave.lockingNumber = this.entity?.lockingNumber !== undefined ? this.entity.lockingNumber : null;
		return objToSave;
	}

	private fetchEntity(id: number | string | null): Observable<TEntity> {
		if (id) {
			return this.service.getById(id);
		} else {
			if (this.newEntity) {
				const newEntity = this.newEntity();
				return newEntity instanceof Observable ? newEntity : of(newEntity);
			} else {
				return of({} as TEntity);
			}
		}
	}

	private doSave() {
		this.pendingSave = true;
		const objToSave: TEntity = this.getObjectToSave();
		(this.onSave ? this.onSave(objToSave) : this.service.save(objToSave, this.form))
			.pipe(finalize(() => this.pendingSave = false))
			.subscribe(response => {
				if (this.afterSave) {
					this.afterSave(response);
				} else {
					this.goBack();
				}
			});
	}
}